    expect(run).toContain("export ATOMA_PROVIDER");
  });
});

/**
 * The step's bash, executed.
 *
 * A stub `atoma` writes the arguments it was given to a file and exits with a
 * code this decides -- so the exit code is what is under test, and the argument
 * is observable without printing it (a run whose credential is present prints
 * nothing at all, which is one of the properties here).
 */
const STUB_ATOMA = `#!/usr/bin/env bash
{
  for arg in "$@"; do printf '%s\\n' "$arg"; done
  printf 'ATOMA_PROVIDER=%s\\n' "\${ATOMA_PROVIDER-unset}"
} >> "$STUB_ARGS"
printf '%s' "$STUB_OUTPUT"
exit "\${STUB_EXIT:-0}"
`;

interface CheckRun {
  code: number;
  stdout: string;
  stderr: string;
  /** The arguments the check passed to `atoma`, one per line. */
  args: string[];
  definition: string;
}

function runCheck(options: {
  present?: string[];
  atomaExit?: number;
  atomaOutput?: string;
  providerIn?: string;
}): CheckRun {
  const dir = mkdtempSync(join(tmpdir(), "atomaton-provider-credential-"));
  try {
    writeFileSync(join(dir, "atoma"), STUB_ATOMA);
    chmodSync(join(dir, "atoma"), 0o755);
    const argsFile = join(dir, "args");
    writeFileSync(argsFile, "");

    const env: Record<string, string> = {
      PATH: `${dir}:${process.env.PATH ?? ""}`,
      ATOMATON_MACHINERY_ROOT: dir,
      AGENT: "engineer",
      ATOMA_PROVIDER_IN: options.providerIn ?? "",
      STUB_ARGS: argsFile,
      STUB_EXIT: String(options.atomaExit ?? 0),
      STUB_OUTPUT: options.atomaOutput ?? "",
    };
    for (const name of options.present ?? []) env[`${name}_PRESENT`] = "true";

    // `bash -e`, which is what GitHub Actions runs a `run:` block with.
    const result = Bun.spawnSync({
      cmd: ["bash", "-e", "-c", checkStep().run ?? ""],
      env,
      stdout: "pipe",
      stderr: "pipe",
    });

    return {
      code: result.exitCode ?? -1,
      stdout: result.stdout.toString(),
      stderr: result.stderr.toString(),
      args: readFileSync(argsFile, "utf8").replace(/\n$/, "").split("\n"),
      definition: `${dir}/.github/atomaton/agent-definitions/engineer.md`,
    };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

describe("what the check does with an exit code", () => {
  test("a run that has the credential continues, and says nothing", () => {
    const run = runCheck({
      present: ["ORCAROUTER_API_KEY"],
      atomaExit: 0,
      atomaOutput: "✓ Agent definition parsed: engineer\n\nValidation passed.\n",
    });

    expect(run.code, run.stderr).toBe(0);
    // `validate` prints its whole report to stdout, and this runs on every run of
    // every project. A check that has nothing to report says nothing.
    expect(run.stdout, "the check adds output to a run that was already fine").toBe("");
    expect(run.args, "the definition the agent will run, and the names this run has").toEqual([
      "--agent-def",
      run.definition,
      "--credentials-present",
      "ORCAROUTER_API_KEY",
    ]);
  });

  test("a run that does not have it stops, with the message that names the secret", () => {
    const run = runCheck({
      atomaExit: 1,
      atomaOutput:
        "Error: ORCAROUTER_API_KEY is not set, and the orcarouter-responses provider authenticates with it. " +
        "Set it, or choose another provider with ATOMA_PROVIDER.\n",
    });

    expect(run.code, "the run must not continue without a credential").toBe(1);
    expect(run.stderr, "the core's own message has to reach the log").toContain("ORCAROUTER_API_KEY is not set");
    expect(run.stderr, "and the annotation a person reads on the run summary").toContain("::error::");
    expect(run.stderr).toContain("::error::Error: ORCAROUTER_API_KEY is not set");
  });

  test("a run with no credentials at all states that, rather than omitting the flag", () => {
    const run = runCheck({
      atomaExit: 1,
      atomaOutput: "Error: No provider credential is set. Set one of ANTHROPIC_API_KEY, ...\n",
    });

    expect(run.code).toBe(1);
    // Empty is a caller saying "none are set", which is a state worth being able
    // to state -- and the alternative, leaving the flag off, means "do not look
    // at credentials at all", which is the opposite answer.
    expect(run.args[3], "an empty list must be passed, not dropped").toBe("");
    expect(run.stderr).toContain("No provider credential is set");
  });

  test("a check that could not be run does not stop the run", () => {
    const run = runCheck({
      atomaExit: 2,
      atomaOutput: "error: unexpected argument '--credentials-present' found\n",
    });

    // Above 1 is "the check did not happen" -- clap rejecting the flag on an
    // atoma older than it is 2 -- and reading that as "the credential is
    // missing" would fail every run of every project on that binary.
    expect(run.code, "the check not happening must not fail the run").toBe(0);
    expect(run.stderr).toContain("::warning::");
  });

  test("a command that could not be started at all does not stop the run either", () => {
    const run = runCheck({ atomaExit: 127, atomaOutput: "atoma: command not found\n" });
    expect(run.code).toBe(0);
    expect(run.stderr).toContain("::warning::");
  });

  test("the names it states are the ones this run has, in the run's own order", () => {
    const run = runCheck({ present: ["ORCAROUTER_API_KEY", "OPENAI_API_KEY"], atomaExit: 0 });
    expect(run.args[3]).toBe("OPENAI_API_KEY,ORCAROUTER_API_KEY");
  });

  test("the provider variable reaches the check only when it is set", () => {
    expect(runCheck({ present: ["ANTHROPIC_API_KEY"], providerIn: "anthropic" }).args).toContain(
      "ATOMA_PROVIDER=anthropic",
    );
    // Empty would defeat the core's auto-detection, which is what the `_IN`
    // suffix in the run step exists for. The check has to agree, or it asks the
    // core a question the run will not ask.
    expect(runCheck({ present: ["ANTHROPIC_API_KEY"] }).args).toContain("ATOMA_PROVIDER=unset");
  });
});
