{"content": "/**
 * provider-credential-check.test.ts — the step that stops a run before it builds
 * anything, when the provider it will resolve to has no credential.
 *
 * Switching provider is an ordinary edit: `provider:` in an agent definition, or
 * `ATOMA_PROVIDER` as a repository variable. Adding the secret that provider
 * authenticates with is a separate one, and nothing noticed when it was missed
 * until the core tried to build a client — after the checkout, after the
 * dependencies, after the tool servers. A whole runner, spent to learn something
 * that was knowable in the first minute.
 *
 * ## Two halves, because the interesting part is an exit code
 *
 * The static half reads the GENERATED workflow, which is what an adopter receives
 * and what runs — including the ordering, which is the whole feature: before the
 * environment is built, and before the run has left anything behind.
 *
 * The executable half runs the step's own bash with a stub `atoma` on PATH. What
 * the step does is decide what to do about an exit code — continue, warn, or stop
 * naming a secret — and a claim about that which was never executed is a claim
 * about a string.
 *
 * ## What is deliberately not asserted
 *
 * That the check knows which credential any provider needs. It must not: that
 * table is the core's, and the core is what this step asks. The assertion for
 * that is negative — the step names no provider — and it is what lets this check
 * survive the core adding one.
 */
import { describe, expect, test } from "bun:test";
import { chmodSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { RUN_CREDENTIALS } from "../../src/domain/declared-secrets.ts";
import {
  AGENT_DEFINITIONS_DIR,
  RUNTIME_ROOT,
} from "../../src/domain/machinery-layout.ts";

const RUNNER = "dist/.github/workflows/atomaton-runner.yml";
const CHECK_STEP = "Check the provider credential is present";
const SETUP_STEP = "Run configured environment setup";
const INSTALL_STEP = "Install Atoma CLI";
const LABEL_STEP = "Add atomaton/in-progress label";
const AGENT_STEP = "Run agent";

interface Step {
  name?: string;
  run?: string;
  env?: Record<string, string>;
  if?: string;
}

function runnerSteps(): Step[] {
  const doc = Bun.YAML.parse(readFileSync(RUNNER, "utf8")) as {
    jobs?: Record<string, { steps?: Step[] }>;
  };
  const steps = doc.jobs?.run?.steps;
  expect(steps, `${RUNNER} has no "run" job`).toBeDefined();
  return steps ?? [];
}

function stepNames(): string[] {
  return runnerSteps().map((step) => step.name ?? "");
}

function checkStep(): Step {
  const step = runnerSteps().find((candidate) => candidate.name === CHECK_STEP);
  // Named explicitly, so a renamed or dropped step fails here rather than making
  // every assertion below pass by finding nothing.
  expect(step, `${RUNNER} has no step named "${CHECK_STEP}"`).toBeDefined();
  return step!;
}

/** `${{ secrets.NAME != '' }}`, or the one name whose value is not a secret. */
const PRESENCE = /^\$\{\{ (secrets\.[A-Z][A-Z0-9_]*|github\.token) != '' \}\}$/;

/** Provider names, read out of the configuration reference's table. */
function providerNames(): string[] {
  const docs = readFileSync("docs/configuration.md", "utf8");
  const names = new Set<string>();
  for (const line of docs.split(/\r?\n/)) {
    const match = /^\|\s*`([a-z][a-z0-9-]*)`\s*\|[^|]*\|\s*`[A-Z][A-Z0-9_]*`\s*\|/.exec(line);
    if (match?.[1]) names.add(match[1]);
  }
  expect(names.size, "the provider table was not found, so this test checks nothing").toBeGreaterThan(4);
  return [...names];
}

describe("the provider credential check", () => {
  test("it runs before the environment is built, and before this run leaves anything behind", () => {
    const names = stepNames();
    const check = names.indexOf(CHECK_STEP);
    expect(check, `${RUNNER} has no step named "${CHECK_STEP}"`).toBeGreaterThanOrEqual(0);

    for (const label of [INSTALL_STEP, SETUP_STEP, LABEL_STEP, AGENT_STEP]) {
      expect(names.indexOf(label), `the runner no longer has a step named "${label}"`).toBeGreaterThanOrEqual(0);
    }

    // The binary first, because the step IS a call to it.
    expect(names.indexOf(INSTALL_STEP), `${INSTALL_STEP} must install the binary the check runs`).toBeLessThan(check);
    // And then the point of the whole step: the packages, the project's own setup
    // commands and the tool servers all come after it, so a run that cannot
    // authenticate never pays for them.
    expect(check, "the credential must be checked before the environment setup runs").toBeLessThan(
      names.indexOf(SETUP_STEP),
    );
    expect(check, "and long before the agent starts").toBeLessThan(names.indexOf(AGENT_STEP));
    // The in-progress label is added before the agent runs and removed only by a
    // guard that requires the agent to have finished. Stopping after it is added
    // leaves the label on the issue for a person to clean up by hand.
    expect(check, "a run that stops here must leave nothing behind").toBeLessThan(names.indexOf(LABEL_STEP));

    // Unconditional. It cannot be gated on an output -- nothing that could decide
    // has run yet -- and a check that can be skipped is not one.
    expect(checkStep().if, "the credential check must not be conditional").toBeUndefined();
  });

  test("the check holds names and never a credential value", () => {
    const step = checkStep();
    const env = step.env ?? {};
    expect(Object.keys(env).length, "the check step carries no environment").toBeGreaterThan(0);

    let flags = 0;
    for (const [name, value] of Object.entries(env)) {
      expect(
        value,
        `${name} in the check step is not a presence comparison. Only a boolean may arrive here: ` +
          `a value would put a credential in a step whose bash lives for as long as it takes the ` +
          `core to answer, next to nothing else that runs this early`,
      ).toMatch(PRESENCE);
      if (name.endsWith("_PRESENT")) flags += 1;
    }
    expect(flags, "no NAME_PRESENT flags, so the check asks about nothing").toBeGreaterThan(0);

    // And nothing is spliced into the shell text either, which is the other way a
    // step acquires something it should not hold.
    expect(step.run, "the check interpolates an expression into its own bash").not.toContain("${{");
  });

  test("every credential the run supplies is asked about, and nothing else", () => {
    const step = checkStep();
    const env = step.env ?? {};

    for (const name of RUN_CREDENTIALS) {
      expect(
        Object.keys(env),
        `${name} is in RUN_CREDENTIALS, so the check must ask about it -- otherwise a run whose ` +
          `provider is the one that reads it is stopped with the secret already set`,
      ).toContain(`${name}_PRESENT`);
      expect(step.run, `${name} must reach the list the check builds for --credentials-present`).toContain(name);
    }

    const asked = Object.keys(env)
      .filter((name) => name.endsWith("_PRESENT"))
      .map((name) => name.replace(/_PRESENT$/, ""))
      .sort();
    expect(asked, "the check asks about a name the run does not supply").toEqual([...RUN_CREDENTIALS].sort());
  });

  test("the check carries no provider-to-credential table of its own", () => {
    const run = checkStep().run ?? "";

    for (const provider of providerNames()) {
      expect(
        run,
        `the check names the provider '${provider}', which means it has started deciding something. ` +
          `Which credential a provider needs, and which provider a run resolves to, are the core's ` +
          `tables -- a copy here is right until the core adds a provider`,
      ).not.toContain(provider);
    }

    expect(run, "the core must be the one asked").toContain("atoma validate");
    expect(run, "and asked for the one question the flag exists for").toContain("--credentials-present");
  });

  test("the provider variable is passed the way the run passes it", () => {
    const env = checkStep().env ?? {};
    const run = checkStep().run ?? "";

    // The repository variable, under its `_IN` name. An empty ATOMA_PROVIDER in
    // the environment would defeat the core's own auto-detection, so it is
    // promoted only when non-empty -- the same rule the agent step applies to the
    // same two names, and for the same reason.
    expect(env.ATOMA_PROVIDER_IN, "the check step does not receive the provider variable").toBe(
      "${{ vars.ATOMA_PROVIDER }}",
    );
    expect(env.ATOMA_PROVIDER, "an empty ATOMA_PROVIDER would defeat auto-detection").toBeUndefined();
    expect(run).toContain("ATOMA_PROVIDER_IN");
    expect(run).toContain('export ATOMA_PROVIDER="\${ATOMA_PROVIDER_IN}"');
  });

  test("it reads the definition the agent will run, from the machinery", () => {
    const run = checkStep().run ?? "";
    // The same path the agent step passes to `atoma run`. Reading it from the
    // checkout instead would let a pull request choose which provider
    // authenticates the run reviewing it -- the rule the machinery checkout exists
    // for.
    expect(run).toContain(`\${ATOMATON_MACHINERY_ROOT}/${AGENT_DEFINITIONS_DIR}/\${AGENT}.md`);

    const agent = runnerSteps().find((step) => step.name === AGENT_STEP);
    expect(agent?.run, "the agent step no longer names a definition").toContain(
      `--agent-def "\${ATOMATON_MACHINERY_ROOT}/${AGENT_DEFINITIONS_DIR}/\${AGENT}.md"`,
    );
  });

  test("the core's own command line, not a copy of it, comes from the shared installer", () => {
    // The install step and the check are one ordering: what the check runs, the
    // step above it put there. Asserted as a proximity rather than a name, so
    // reordering the two fails.
    const names = stepNames();
    expect(
      names.indexOf(CHECK_STEP) - names.indexOf(INSTALL_STEP),
      "the check belongs directly after the install, with nothing between",
    ).toBeGreaterThan(0);
    expect(RUNTIME_ROOT, "the layout constant is imported for its own sake").toContain("atomaton-runtime");
  });
});

/**
 * The step's bash, executed.
 *
 * A stub `atoma` records the arguments it was given and exits with a code the
 * test chooses, so the exit code is what is under test and the argument is
 * observable without the step printing anything at all -- which is one of the
 * properties here.
 */
const STUB_ATOMA = `#!/usr/bin/env bash
{
  for arg in "$@"; do printf '%s\\n' "$arg"; done
  printf 'ATOMA_PROVIDER=%s\\n' "\${ATOMA_PROVIDER-unset}"
} >> "$STUB_ARGS"
printf '%s' "\${STUB_STDOUT:-}"
printf '%s' "\${STUB_STDERR:-}" >&2
exit "\${STUB_EXIT:-0}"
`;

interface CheckRun {
  code: number;
  stdout: string;
  stderr: string;
  /** The arguments the check passed to `atoma`, one per line. */
  args: string[];
  definition: string;
}

function runCheck(options: {
  present?: string[];
  atomaExit?: number;
  atomaStdout?: string;
  atomaStderr?: string;
  providerIn?: string;
}): CheckRun {
  const dir = mkdtempSync(join(tmpdir(), "atomaton-provider-credential-"));
  try {
    writeFileSync(join(dir, "atoma"), STUB_ATOMA);
    chmodSync(join(dir, "atoma"), 0o755);
    const argsFile = join(dir, "args");
    writeFileSync(argsFile, "");

    const env: Record<string, string> = {
      PATH: `${dir}:${process.env.PATH ?? ""}`,
      ATOMATON_MACHINERY_ROOT: dir,
      AGENT: "engineer",
      ATOMA_PROVIDER_IN: options.providerIn ?? "",
      STUB_ARGS: argsFile,
      STUB_EXIT: String(options.atomaExit ?? 0),
      STUB_STDOUT: options.atomaStdout ?? "",
      STUB_STDERR: options.atomaStderr ?? "",
    };
    for (const name of options.present ?? []) env[`${name}_PRESENT`] = "true";

    // `bash -e`, which is what GitHub Actions runs a `run:` block with.
    const result = Bun.spawnSync({
      cmd: ["bash", "-e", "-c", checkStep().run ?? ""],
      env,
      stdout: "pipe",
      stderr: "pipe",
    });

    return {
      code: result.exitCode ?? -1,
      stdout: result.stdout.toString(),
      stderr: result.stderr.toString(),
      args: readFileSync(argsFile, "utf8").replace(/\n$/, "").split("\n"),
      definition: `${dir}/${AGENT_DEFINITIONS_DIR}/engineer.md`,
    };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

describe("what the check does with an exit code", () => {
  test("a run that has the credential continues, and says nothing", () => {
    const run = runCheck({
      present: ["ORCAROUTER_API_KEY"],
      atomaExit: 0,
      atomaStdout: "✓ Agent definition parsed: engineer\n  ✓ provider 'orcarouter-responses' is known\n\nValidation passed.\n",
    });

    expect(run.code, run.stderr).toBe(0);
    // `validate` prints its whole report on every run of every project. A check
    // with nothing to report says nothing.
    expect(run.stdout, "the check adds output to a run that was already fine").toBe("");
    expect(run.stderr, "and nothing to the log either").toBe("");
    expect(run.args, "the definition the agent will run, and the names this run has").toEqual([
      "--agent-def",
      run.definition,
      "--credentials-present",
      "ORCAROUTER_API_KEY",
    ]);
  });

  test("a run that does not have it stops, with the message that names the secret", () => {
    const coreMessage =
      "Error: ORCAROUTER_API_KEY is not set, and the orcarouter-responses provider authenticates with it. " +
      "Set it, or choose another provider with ATOMA_PROVIDER.\n";
    const run = runCheck({ atomaExit: 1, atomaStdout: "Validation passed.\n", atomaStderr: coreMessage });

    expect(run.code, "the run must not continue without a credential").toBe(1);
    expect(run.stderr, "the core's own message has to reach the log").toContain("ORCAROUTER_API_KEY is not set");
    expect(run.stderr, "and the annotation a person reads on the run summary").toContain(
      "::error::Error: ORCAROUTER_API_KEY is not set",
    );
    expect(run.stdout, "and the report of a check that passed is not what they need").toBe("");
  });

  test("a run with no credentials at all states that, rather than omitting the flag", () => {
    const run = runCheck({
      atomaExit: 1,
      atomaStderr: "Error: No provider credential is set. Set one of ANTHROPIC_API_KEY, ...\n",
    });

    expect(run.code).toBe(1);
    // Empty is a caller saying "none are set", which is a state worth being able
    // to state. Leaving the flag off means "do not look at credentials at all",
    // which is the opposite answer.
    expect(run.args[3], "an empty list must be passed, not dropped").toBe("");
    expect(run.stderr).toContain("No provider credential is set");
  });

  test("a run whose provider resolved by auto-detection and found two gets the core's error", () => {
    const run = runCheck({
      present: ["OPENAI_API_KEY", "OPENROUTER_API_KEY"],
      atomaExit: 1,
      atomaStderr:
        "Error: More than one provider credential is set (OPENAI_API_KEY, OPENROUTER_API_KEY), so which one " +
        "to use is not decided by the credentials.\n",
    });

    // The rule this catches is the core's, and it is stated here only to show the
    // step does not need to know it: it asked, and was told.
    expect(run.code).toBe(1);
    expect(run.stderr).toContain("More than one provider credential is set");
  });

