{"new_string": "  test("the check holds names and never a credential value", () => {
    const step = checkStep();
    const env = step.env ?? {};
    expect(Object.keys(env).length, "the check step carries no environment").toBeGreaterThan(0);

    let flags = 0;
    for (const [name, value] of Object.entries(env)) {
      // The provider is a repository VARIABLE, not a credential: a name, and the
      // whole point of not having to write the provider down here is that it is
      // not a secret. Pinned by its own test below.
      if (name === "ATOMA_PROVIDER_IN") continue;
      if (name === "AGENT") continue;
      expect(
        value,
        `${name} in the check step is not a presence comparison. Only a boolean may arrive here: ` +
          `a value would put a credential in a step whose bash runs next to nothing else this early`,
      ).toMatch(PRESENCE);
      flags += 1;
    }
    expect(
      flags,
      "no NAME_PRESENT flags, so the check asks about nothing (or something in this step stopped looking " +
        "like a presence comparison, which is the failure this catches)",
    ).toBe(RUN_CREDENTIALS.length);

    // And nothing is spliced into the shell text either, which is the other way a
    // step acquires something it should not hold.
    expect(step.run, "the check interpolates an expression into its own bash").not.toContain("${{");
